    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    for i in range(2):
        for j in range(2):
            new_str = lst[i] + lst[j]
            if is_balanced(new_str):
                return 'Yes'

    return 'No'

