def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    for s in lst:
        if not all(c in ['(', ')'] for c in s):
            return 'No'

    total_open = sum(s.count('(') for s in lst)
    total_close = sum(s.count(')') for s in lst)

    if (total_open + total_close) % 2 != 0:
        return 'No'

    balance = 0
    for s in lst:
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return 'No'

    return 'Yes'

